def classify(text):
    t = text.lower()
    votes = {"program": t.count("def ") + t.count("{"),
             "measurement": t.count("kg") + t.count("cm"),
             "instruction": t.count("step ") + t.count("first,")}
    return max(votes, key=votes.get)
print(classify("def f(x): return x"))
print(classify("Step 1: add 2kg flour"))

