def features(text):
    toks = text.split()
    return {"code_ratio": sum(1 for w in toks if "(" in w) / max(len(toks), 1),
            "num_ratio": sum(1 for w in toks if any(c.isdigit() for c in w)) / max(len(toks), 1)}
print(features("measure 2kg then def f(x): return (x)"))

